WITH subq1 AS ( WITH inner_cte AS ( SELECT t1.SUBJECT_CODE, t1.SUBJECT_TITLE, t1.DEPARTMENT_NAME, t0.SCHOOL_NAME FROM SIS_DEPARTMENT t0 JOIN COURSE_CATALOG_SUBJECT_OFFERED t1 ON t0.DEPARTMENT_CODE = t1.DEPARTMENT_CODE WHERE t1.ACADEMIC_YEAR = 2024 AND t1.TOTAL_UNITS = 12 AND t1.DEPARTMENT_NAME = 'Mathematics' ) SELECT ic.SUBJECT_CODE, ic.SUBJECT_TITLE, ic.DEPARTMENT_NAME, ic.SCHOOL_NAME, sc.subject_count FROM inner_cte ic JOIN ( SELECT SCHOOL_NAME, COUNT(*) AS subject_count FROM inner_cte GROUP BY SCHOOL_NAME HAVING COUNT(*) >= 2 ) sc ON ic.SCHOOL_NAME = sc.SCHOOL_NAME ), subq2 AS ( WITH inner_cte AS ( SELECT sd.DEPARTMENT_NAME, VARIANCE(ccc.TOTAL_UNITS) AS variance_total_units, STDDEV(ccc.TOTAL_UNITS) AS stddev_total_units FROM SIS_DEPARTMENT sd JOIN CIS_COURSE_CATALOG ccc ON sd.DEPARTMENT_CODE = ccc.DEPARTMENT_CODE WHERE sd.IS_DEGREE_GRANTING = 'Y' AND ccc.TOTAL_UNITS IS NOT NULL GROUP BY sd.DEPARTMENT_NAME ) SELECT ic.DEPARTMENT_NAME, ic.variance_total_units, ic.stddev_total_units, sd.SCHOOL_NAME FROM inner_cte ic JOIN SIS_DEPARTMENT sd ON ic.DEPARTMENT_NAME = sd.DEPARTMENT_NAME ) SELECT s1.SUBJECT_CODE, s1.SUBJECT_TITLE, s1.DEPARTMENT_NAME, s1.SCHOOL_NAME, s1.subject_count, s2.variance_total_units, s2.stddev_total_units FROM subq1 s1 JOIN subq2 s2 ON s1.DEPARTMENT_NAME = s2.DEPARTMENT_NAME AND s1.SCHOOL_NAME = s2.SCHOOL_NAME ORDER BY s1.SCHOOL_NAME, s1.SUBJECT_CODE;